/* separator styles */
.sc_relative {
    position: relative !important;
}
.sc_separator{
	position: absolute; 
    z-index: 0;
    display: grid;
    /*width: calc(100% + 0px);
    margin-left: -1px;*/

    overflow: hidden;
    left: 0;
    width: 100%;
    line-height: 0;
    direction: ltr;
}
.sc_separator svg {
    transform: translateX(-50%);
    left: 50%;
    position: relative;
    width: calc(100% + 1px);
}
.sc_sep_top {
    top: -2px;
    transform: rotateX(180deg);
}
.sc_sep_rotatey_top {
    top: -2px;
    transform: rotateX(180deg) rotateY(180deg);
}
.sc_sep_bottom {
    bottom: -1px;
}	
.sc_sep_rotatey_bottom {
    bottom: -1px;
    transform: rotateY(180deg);
}

.parallax1 > use {
  animation: move-forever1 10s linear infinite;
  &:nth-child(1) {
    animation-delay: -2s;
  }
}
.parallax2 > use {
  animation: move-forever2 8s linear infinite;
  &:nth-child(1) {
    animation-delay: -2s;
  }
}
.parallax3 > use {
  animation: move-forever3 6s linear infinite;
  &:nth-child(1) {
    animation-delay: -2s;
  }
}
.parallax4 > use {
  animation: move-forever4 4s linear infinite;
  &:nth-child(1) {
    animation-delay: -2s;
  }
}
@keyframes move-forever1 {
  0% {
    transform: translate(85px, 0%);
  }
  100% {
    transform: translate(-90px, 0%);
  }
}
@keyframes move-forever2 {
  0% {
    transform: translate(-90px, 0%);
  }
  100% {
    transform: translate(85px, 0%);
  }
}
@keyframes move-forever3 {
  0% {
    transform: translate(85px, 0%);
  }
  100% {
    transform: translate(-90px, 0%);
  }
}
@keyframes move-forever4 {
  0% {
    transform: translate(-90px, 0%);
  }
  100% {
    transform: translate(85px, 0%);
  }
}

